mapper.select:


    LEFT JOIN vm_device_info_t d on FIND_IN_SET(d.device_code,p.park_device_codes)
    LEFT JOIN vm_tenant_device_channel_rel_t ten ON FIND_IN_SET( ten.device_code, p.park_device_codes )

where  p.delete_flag = 0
     and p.park_name like concat('%', #{parkName}, '%')
     and p.park_carrying_capacity = #{parkCarryingCapacity}
     and p.park_traffic_count = #{parkTrafficCount}
     and FIND_IN_SET(#{parkDeviceCodes},p.park_device_codes)
     and p.park_desc = #{parkDesc}
     and p.tenant_id = #{tenantId}
     and p.creator_date = #{creatorDate}
     and p.modifier = #{modifier}
     and p.modifier_date = #{modifierDate}

        and (d.device_name like concat('%', #{devName}, '%') OR ten.device_name LIKE concat('%', #{devName}, '%'))

     ${dataScope}
 GROUP BY p.park_code


        order by creator_date asc


        order by creator_date desc


        order by modifier_date asc


        order by modifier_date desc


        order by p.park_code desc



    limit #{offset},#{limit}


where  p.delete_flag = 0
 and p.park_name = #{parkName}
 and p.park_code != #{parkCode}
${dataScope}

SELECT COUNT( DISTINCT p.park_code) from vm_park_device_info p

    LEFT JOIN vm_device_info_t d on FIND_IN_SET(d.device_code,p.park_device_codes)
    LEFT JOIN vm_tenant_device_channel_rel_t ten ON FIND_IN_SET( ten.device_code, p.park_device_codes )

where p.delete_flag = 0
     and p.park_name like concat('%', #{parkName}, '%')
     and p.park_carrying_capacity = #{parkCarryingCapacity}
     and p.park_traffic_count = #{parkTrafficCount}
     and FIND_IN_SET(#{parkDeviceCodes},p.park_device_codes)             and p.park_desc = #{parkDesc}
     and p.tenant_id = #{tenantId}
     and p.creator_date = #{creatorDate}
     and p.modifier = #{modifier}
     and p.modifier_date = #{modifierDate}

        and (d.device_name like concat('%', #{devName}, '%') OR ten.device_name LIKE concat('%', #{devName}, '%'))

${dataScope}

